'use client';
/**
 * Loupe — the photo view's hands-on control. A jeweller's lens that rests in the corner of the stage: drag it over
 * the speaker to see the render at 2×, throw it and it keeps its velocity, then settles on the nearest numbered
 * detail (magnetic within a small radius) or wherever it was let go. Pressing it steps through the details, the
 * arrow keys nudge it and Escape puts it back, so the same inspection works without a pointer.
 * Physics: one spring per axis plus the open/closed scale, integrated on a useRafLoop that sleeps at rest.
 */
import { useEffect, useId, useRef, useState, type KeyboardEvent, type PointerEvent } from 'react';
import { spring as SPRING, useElementSize, useRafLoop } from '../../../motion';
import { DETAILS } from './data';
import { atRest, axis, clamp, smoothstep, stepAxis } from './physics';
import styles from './styles.module.css';

/** Magnification of the lens. The render is 1024 px, so 2× at the stage's size stays close to native resolution. */
const ZOOM = 2;
/** Resting place, in the poster box (0–1): bottom-right, over empty paper. */
const DOCK = { u: 0.9, v: 0.9 } as const;
/** Within this distance (poster-box units) a released lens settles on a detail; the pull starts at twice that. */
const SNAP = 0.12;
const SCALE_DOCKED = 0.4;
/** How far a throw carries (s): the release point is projected along the velocity before choosing where to land. */
const PROJECT = 0.18;

type Mode = 'dock' | 'free' | 'detail';

export function Loupe({ src, active, onActive, onEngage, reduced }: {
  src: string;
  active: string | null;
  onActive: (id: string | null) => void;
  /** True while the lens is held: the stage flattens its tilt so the lens sits exactly on what it magnifies. */
  onEngage: (held: boolean) => void;
  reduced: boolean;
}) {
  const hintId = useId();
  const layer = useRef<HTMLDivElement>(null);
  const lens = useRef<HTMLButtonElement>(null);
  const glass = useRef<HTMLSpanElement>(null);
  const size = useElementSize(layer);
  const sim = useRef({ u: axis(DOCK.u), v: axis(DOCK.v), s: axis(SCALE_DOCKED), tu: DOCK.u as number, tv: DOCK.v as number, ts: SCALE_DOCKED as number });
  const drag = useRef<{ id: number; du: number; dv: number; x0: number; y0: number; moved: boolean } | null>(null);
  const suppressClick = useRef(false);
  const mode = useRef<Mode>('dock');
  const [open, setOpen] = useState(false);
  const [near, setNear] = useState<string | null>(null);
  const [running, setRunning] = useState(false);
  const runningRef = useRef(false);

  const write = () => {
    const el = lens.current, g = glass.current;
    const { u, v, s } = sim.current;
    if (!el || !g || size.width < 1) return;
    const L = el.offsetWidth;
    el.style.transform = `translate3d(${(u.x * size.width).toFixed(2)}px, ${(v.x * size.height).toFixed(2)}px, 0) translate(-50%, -50%) scale(${s.x.toFixed(4)})`;
    el.style.setProperty('--open', clamp((s.x - SCALE_DOCKED) / (1 - SCALE_DOCKED), 0, 1).toFixed(3));
    g.style.backgroundSize = `${(size.width * ZOOM).toFixed(1)}px ${(size.height * ZOOM).toFixed(1)}px`;
    g.style.backgroundPosition = `${(L / 2 - u.x * size.width * ZOOM).toFixed(1)}px ${(L / 2 - v.x * size.height * ZOOM).toFixed(1)}px`;
  };

  const wake = () => {
    if (reduced) {
      const st = sim.current;
      st.u = axis(st.tu); st.v = axis(st.tv); st.s = axis(st.ts);
      write();
      return;
    }
    if (runningRef.current) return;
    runningRef.current = true;
    setRunning(true);
  };

  const aim = (u: number, v: number, s: number) => {
    const st = sim.current;
    st.tu = clamp(u, 0.06, 0.94); st.tv = clamp(v, 0.06, 0.94); st.ts = s;
    wake();
  };

  const toDock = () => {
    mode.current = 'dock';
    setOpen(false);
    setNear(null);
    aim(DOCK.u, DOCK.v, SCALE_DOCKED);
  };
  const toDetail = (id: string) => {
    const d = DETAILS.find((x) => x.id === id);
    if (!d) return;
    mode.current = 'detail';
    setOpen(true);
    setNear(id);
    aim(d.at.x / 100, d.at.y / 100, 1);
  };

  // Keep the lens where it is when the stage resizes.
  useEffect(() => { write(); }); // eslint-disable-line react-hooks/exhaustive-deps

  // The markers are the twin: choosing one flies the lens to it; closing the detail elsewhere docks it.
  useEffect(() => {
    if (drag.current) return;
    if (active) { if (!(mode.current === 'detail' && near === active)) toDetail(active); }
    else if (mode.current === 'detail') toDock();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active]);

  useRafLoop(layer, (dt) => {
    const st = sim.current;
    const held = !!drag.current;
    const move = held ? SPRING.settle : SPRING.release;
    stepAxis(st.u, st.tu, move, dt);
    stepAxis(st.v, st.tv, move, dt);
    stepAxis(st.s, st.ts, SPRING.pop, dt);
    write();
    if (!held && atRest(st.u, st.tu, 0.0005) && atRest(st.v, st.tv, 0.0005) && atRest(st.s, st.ts, 0.002)) {
      st.u = axis(st.tu); st.v = axis(st.tv); st.s = axis(st.ts);
      write();
      runningRef.current = false;
      setRunning(false);
    }
  }, running && !reduced);

  const nearest = (u: number, v: number) => {
    let best: { id: string; d: number; u: number; v: number } | null = null;
    for (const d of DETAILS) {
      const du = d.at.x / 100 - u, dv = d.at.y / 100 - v, dist = Math.hypot(du, dv);
      if (!best || dist < best.d) best = { id: d.id, d: dist, u: d.at.x / 100, v: d.at.y / 100 };
    }
    return best;
  };

  const local = (e: PointerEvent) => {
    const r = layer.current?.getBoundingClientRect();
    if (!r || r.width < 1) return { u: 0.5, v: 0.5 };
    return { u: (e.clientX - r.left) / r.width, v: (e.clientY - r.top) / r.height };
  };

  const onPointerDown = (e: PointerEvent<HTMLButtonElement>) => {
    if (e.button !== 0) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    const p = local(e);
    const st = sim.current;
    // Grabbing an open lens keeps the grab offset; a docked one jumps under the pointer as it opens.
    const docked = mode.current === 'dock';
    drag.current = { id: e.pointerId, du: docked ? 0 : st.u.x - p.u, dv: docked ? 0 : st.v.x - p.v, x0: e.clientX, y0: e.clientY, moved: false };
    onEngage(true);
  };

  const onPointerMove = (e: PointerEvent<HTMLButtonElement>) => {
    const g = drag.current;
    if (!g || g.id !== e.pointerId) return;
    if (!g.moved && Math.hypot(e.clientX - g.x0, e.clientY - g.y0) < 4) return;
    if (!g.moved) { g.moved = true; mode.current = 'free'; setOpen(true); }
    const p = local(e);
    let u = p.u + g.du, v = p.v + g.dv;
    // Magnetic pull toward the closest detail as the lens approaches it.
    const n = nearest(u, v);
    if (n && n.d < SNAP * 2) {
      const w = smoothstep(1 - n.d / (SNAP * 2)) * 0.35;
      u += (n.u - u) * w; v += (n.v - v) * w;
    }
    setNear(n && n.d < SNAP ? n.id : null);
    aim(u, v, 1);
  };

  const release = (e: PointerEvent<HTMLButtonElement>) => {
    const g = drag.current;
    if (!g || g.id !== e.pointerId) return;
    drag.current = null;
    onEngage(false);
    if (!g.moved) return; // a press: the click handler steps through the details
    suppressClick.current = true;
    const st = sim.current;
    const pu = st.u.x + st.u.v * PROJECT, pv = st.v.x + st.v.v * PROJECT;
    const n = nearest(pu, pv);
    if (Math.hypot(pu - DOCK.u, pv - DOCK.v) < 0.1) { toDock(); onActive(null); return; }
    if (n && n.d < SNAP) { toDetail(n.id); onActive(n.id); return; }
    mode.current = 'free';
    setNear(null);
    onActive(null);
    aim(pu, pv, 1);
  };

  /** Press (click, Enter, Space): docked → detail 1 → 2 → 3 → docked. */
  const onClick = () => {
    if (suppressClick.current) { suppressClick.current = false; return; }
    const i = mode.current === 'detail' ? DETAILS.findIndex((d) => d.id === near) : -1;
    const next = DETAILS[i + 1];
    if (mode.current === 'dock' || next) { const id = (mode.current === 'dock' ? DETAILS[0] : next).id; toDetail(id); onActive(id); }
    else { toDock(); onActive(null); }
  };

  const onKeyDown = (e: KeyboardEvent<HTMLButtonElement>) => {
    const step = e.shiftKey ? 0.1 : 0.03;
    const st = sim.current;
    const d = e.key === 'ArrowLeft' ? [-step, 0] : e.key === 'ArrowRight' ? [step, 0] : e.key === 'ArrowUp' ? [0, -step] : e.key === 'ArrowDown' ? [0, step] : null;
    if (e.key === 'Escape' && mode.current !== 'dock') { e.preventDefault(); toDock(); onActive(null); return; }
    if (!d) return;
    e.preventDefault();
    const u = (mode.current === 'dock' ? 0.5 : st.tu) + d[0], v = (mode.current === 'dock' ? 0.55 : st.tv) + d[1];
    const n = nearest(u, v);
    mode.current = 'free';
    setOpen(true);
    if (n && n.d < SNAP * 0.5) { setNear(n.id); onActive(n.id); mode.current = 'detail'; }
    else { setNear(null); if (active) onActive(null); }
    aim(u, v, 1);
  };

  const at = DETAILS.find((d) => d.id === near) ?? null;
  const n = at ? DETAILS.indexOf(at) + 1 : null;
  return (
    <div ref={layer} className={styles.loupeLayer}>
      <button
        ref={lens}
        type="button"
        className={styles.lens}
        data-open={open || undefined}
        data-moving={running || undefined}
        aria-label={open ? `Loupe, ${ZOOM}× ${at ? `on detail ${n}: ${at.label}` : 'over the photo'}` : `Loupe, ${ZOOM}× magnifier`}
        aria-describedby={hintId}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={release}
        onPointerCancel={release}
        onLostPointerCapture={release}
        onClick={onClick}
        onKeyDown={onKeyDown}
      >
        <span ref={glass} className={styles.glass} aria-hidden="true" style={{ backgroundImage: `url(${src})` }} />
        <span className={styles.glint} aria-hidden="true" />
        <svg className={styles.lensIcon} viewBox="0 0 24 24" aria-hidden="true" focusable="false"><circle cx="10.5" cy="10.5" r="6" /><path d="m15 15 5 5" /></svg>
        {n ? <span className={styles.lensBadge} aria-hidden="true">{n}</span> : null}
      </button>
      <span id={hintId} className={styles.srOnly}>Drag it over the speaker to look closer; it settles on the nearest numbered detail. Press it to step through the details, use the arrow keys to move it, Escape to put it back.</span>
    </div>
  );
}

/**
 * Tiny spring integrator for the pointer-driven parts of the page (stage tilt, loupe).
 * Semi-implicit Euler, sub-stepped at ≤ 1/240 s so every motion-token spring stays stable on slow frames.
 */
import type { SpringConfig } from '../../../motion';

export interface Axis { x: number; v: number }
export const axis = (x = 0): Axis => ({ x, v: 0 });

export function stepAxis(a: Axis, target: number, c: SpringConfig, dt: number): void {
  const n = Math.max(1, Math.ceil(dt * 240));
  const h = dt / n;
  for (let i = 0; i < n; i++) {
    a.v += ((-c.stiffness * (a.x - target) - c.damping * a.v) / c.mass) * h;
    a.x += a.v * h;
  }
}

/** Close enough to the target and slow enough that the spring can be put to sleep. */
export const atRest = (a: Axis, target: number, eps: number): boolean => Math.abs(a.x - target) < eps && Math.abs(a.v) < eps * 4;

export const clamp = (v: number, lo: number, hi: number): number => Math.min(hi, Math.max(lo, v));
export const smoothstep = (t: number): number => { const c = clamp(t, 0, 1); return c * c * (3 - 2 * c); };

/**
 * Colourways for the 2D poster without extra renders: the single studio render is tinted in the browser.
 *
 * 1. Classify once: anodised hardware is the only saturated orange (hue 12–48°); the shell is the low-saturation
 *    grey that is NOT the grille plate (convex hull of its bright perforated pixels), NOT the driver cone (a disc
 *    inside the trim ring), NOT the strap (the opaque run above the shell in each column, plus a band along its
 *    right-hand stitching) and NOT the rubber feet.
 * 2. Recolour on demand in linear light: target colour × (pixel luminance ÷ median luminance of its class), with a
 *    soft roll-off above the base so highlights stay highlights. Results are cached as object URLs.
 *
 * The geometry constants are tuned to /models/pulse-speaker.webp (1024 × 1024, generated deterministically).
 */

export interface Tint { shell: string; accent: string }
export interface Recolourer { render(t: Tint): Promise<string | null>; dispose(): void }

const SIZE = 1024;
const DRIVER = { x: 328.8, y: 584.7, r: 92 };
const FEET = [{ x: 275, y: 703, rx: 34, ry: 17 }, { x: 698, y: 822, rx: 38, ry: 19 }];
const STITCH = [[739, 360], [771, 387], [796, 413], [820, 445], [839, 480], [851, 515], [858, 545]] as const;

const LIN = new Float32Array(256).map((_, i) => { const c = i / 255; return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; });
const toSrgb = (l: number): number => {
  const c = l <= 0 ? 0 : l >= 1 ? 1 : l;
  return Math.round(255 * (c <= 0.0031308 ? 12.92 * c : 1.055 * c ** (1 / 2.4) - 0.055));
};
const hexLin = (hex: string): [number, number, number] => [1, 3, 5].map((i) => LIN[parseInt(hex.slice(i, i + 2), 16)]) as [number, number, number];

function hull(points: [number, number][]): [number, number][] {
  const p = [...points].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const cross = (o: number[], a: number[], b: number[]) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const lo: [number, number][] = [], up: [number, number][] = [];
  for (const q of p) { while (lo.length >= 2 && cross(lo[lo.length - 2], lo[lo.length - 1], q) <= 0) lo.pop(); lo.push(q); }
  for (let i = p.length - 1; i >= 0; i--) { const q = p[i]; while (up.length >= 2 && cross(up[up.length - 2], up[up.length - 1], q) <= 0) up.pop(); up.push(q); }
  return lo.slice(0, -1).concat(up.slice(0, -1));
}

function median(values: Float32Array, n: number): number {
  const v = Array.from(values.subarray(0, n)).sort((a, b) => a - b);
  return v[Math.floor(v.length / 2)] || 0.15;
}

export async function createRecolourer(src: string): Promise<Recolourer | null> {
  if (typeof document === 'undefined') return null;
  const img = new Image();
  img.decoding = 'async';
  img.src = src;
  try { await img.decode(); } catch { return null; }

  const canvas = document.createElement('canvas');
  canvas.width = SIZE; canvas.height = SIZE;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  if (!ctx) return null;
  ctx.drawImage(img, 0, 0, SIZE, SIZE);
  let base: ImageData;
  try { base = ctx.getImageData(0, 0, SIZE, SIZE); } catch { return null; }
  const d = base.data;
  const W = SIZE, H = SIZE;
  const hsv = (i: number) => {
    const r = d[i], g = d[i + 1], b = d[i + 2];
    const max = Math.max(r, g, b), min = Math.min(r, g, b), c = max - min;
    let h = 0;
    if (c) h = max === r ? ((g - b) / c + 6) % 6 : max === g ? (b - r) / c + 2 : (r - g) / c + 4;
    return { h: h * 60, s: max ? c / max : 0, v: max / 255 };
  };

  // Exclusion mask drawn with canvas paths: grille hull, driver disc, feet, the strap's stitched side.
  const ext: [number, number][] = [];
  for (let y = 400; y < 840; y++) {
    let lo = -1, hi = -1, n = 0;
    for (let x = 170; x < 760; x++) {
      const i = (y * W + x) * 4;
      if (d[i + 3] < 200) continue;
      const { s, v } = hsv(i);
      if (s < 0.06 && v > 0.6) { if (lo < 0) lo = x; hi = x; n++; }
    }
    if (n > 6) ext.push([lo, y], [hi, y]);
  }
  const mask = document.createElement('canvas');
  mask.width = W; mask.height = H;
  const m = mask.getContext('2d', { willReadFrequently: true });
  if (!m || ext.length < 6) return null;
  const g = hull(ext);
  const cx = g.reduce((a, q) => a + q[0], 0) / g.length, cy = g.reduce((a, q) => a + q[1], 0) / g.length;
  m.fillStyle = '#000';
  m.beginPath();
  g.forEach(([x, y], k) => { const l = Math.hypot(x - cx, y - cy) || 1; const px = x + ((x - cx) / l) * 2.5, py = y + ((y - cy) / l) * 2.5; if (k) m.lineTo(px, py); else m.moveTo(px, py); });
  m.closePath(); m.fill();
  m.beginPath(); m.arc(DRIVER.x, DRIVER.y, DRIVER.r, 0, Math.PI * 2); m.fill();
  for (const f of FEET) { m.beginPath(); m.ellipse(f.x, f.y, f.rx, f.ry, 0, 0, Math.PI * 2); m.fill(); }
  m.strokeStyle = '#000'; m.lineWidth = 34; m.lineCap = 'round'; m.lineJoin = 'round';
  m.beginPath(); STITCH.forEach(([x, y], k) => (k ? m.lineTo(x, y) : m.moveTo(x, y))); m.stroke();
  const ex = m.getImageData(0, 0, W, H).data;
  const strap = new Uint8Array(W * H);
  for (let i = 0; i < W * H; i++) if (ex[i * 4 + 3] > 0) strap[i] = 2; // 2 = excluded from the shell only
  // The strap's top arc: in each column, the first opaque run above the shell (separated from it by a gap).
  for (let x = 215; x < 800; x++) {
    let start = -1, runs = 0;
    for (let y = 150; y <= 520; y++) {
      const o = y < 520 && d[(y * W + x) * 4 + 3] > 8;
      if (o && start < 0) start = y;
      if (!o && start >= 0) {
        if (runs === 0) {
          // only a strap if another opaque run (the shell) follows below
          let more = false;
          for (let k = y + 1; k < 520; k++) if (d[(k * W + x) * 4 + 3] > 8) { more = true; break; }
          if (more) for (let k = start; k < y; k++) strap[k * W + x] = 1;
        }
        runs++; start = -1;
      }
    }
  }
  // Stitch band pixels are strap (excluded from accent too); grille/driver/feet only exclude the shell.
  const band = document.createElement('canvas');
  band.width = W; band.height = H;
  const bctx = band.getContext('2d', { willReadFrequently: true });
  if (bctx) {
    bctx.strokeStyle = '#000'; bctx.lineWidth = 34; bctx.lineCap = 'round'; bctx.lineJoin = 'round';
    bctx.beginPath(); STITCH.forEach(([x, y], k) => (k ? bctx.lineTo(x, y) : bctx.moveTo(x, y))); bctx.stroke();
    const bd = bctx.getImageData(0, 0, W, H).data;
    for (let i = 0; i < W * H; i++) if (bd[i * 4 + 3] > 0) strap[i] = 1;
  }

  const labels = new Uint8Array(W * H); // 0 keep · 1 shell · 2 hardware
  const lum = new Float32Array(W * H);
  const shellL = new Float32Array(W * H), accL = new Float32Array(W * H);
  let ns = 0, na = 0;
  for (let p = 0, i = 0; p < W * H; p++, i += 4) {
    if (d[i + 3] < 4 || strap[p] === 1) continue;
    const { h, s, v } = hsv(i);
    const L = 0.2126 * LIN[d[i]] + 0.7152 * LIN[d[i + 1]] + 0.0722 * LIN[d[i + 2]];
    lum[p] = L;
    if (h >= 12 && h <= 48 && s > 0.3 && v > 0.18) { labels[p] = 2; if ((p & 3) === 0) accL[na++] = L; continue; }
    if (h >= 150 && h <= 205 && s > 0.12) continue; // status light
    if (strap[p] === 2) continue;
    if (s < 0.22) { labels[p] = 1; if ((p & 3) === 0) shellL[ns++] = L; }
  }
  const refShell = median(shellL, ns), refAccent = median(accL, na);

  const urls = new Map<string, string>();
  let disposed = false;
  const render = async (t: Tint): Promise<string | null> => {
    const key = `${t.shell}|${t.accent}`;
    const hit = urls.get(key);
    if (hit) return hit;
    const S = hexLin(t.shell), A = hexLin(t.accent);
    const out = new ImageData(new Uint8ClampedArray(d), W, H);
    const o = out.data;
    for (let p = 0, i = 0; p < W * H; p++, i += 4) {
      const lab = labels[p];
      if (!lab) continue;
      const T = lab === 1 ? S : A;
      const f = lum[p] / (lab === 1 ? refShell : refAccent);
      for (let c = 0; c < 3; c++) {
        let v = T[c] * f;
        if (v > T[c]) v = T[c] + (v - T[c]) * 0.55;
        o[i + c] = toSrgb(v);
      }
    }
    ctx.putImageData(out, 0, 0);
    const blob = await new Promise<Blob | null>((res) => canvas.toBlob(res, 'image/webp', 0.9));
    if (!blob || disposed) return null;
    const url = URL.createObjectURL(blob);
    urls.set(key, url);
    return url;
  };
  return {
    render,
    dispose() { disposed = true; for (const u of urls.values()) URL.revokeObjectURL(u); urls.clear(); },
  };
}

/* Pulse — product photography on seamless paper.
   The backdrop takes the tint of the chosen colourway (light and dark variants defined per colourway), the render is
   recoloured to match, display type is Geist at light weights, and mono appears only in specification labels.
   Light: one key light, top-left at rest; on fine pointers the pointer becomes the key light (sheen under it, floor
   shadow away from it). Elevation is always two shadows: a tight contact shadow and a wide ambient one. */

.root {
  /* Two-layer elevation (contact + ambient), light from the top-left. */
  --sh-rest: 0 1px 1.5px rgb(0 0 0 / 0.2), 0 6px 14px -8px rgb(0 0 0 / 0.32);
  --sh-lift: 0 1px 1px rgb(0 0 0 / 0.14), 0 14px 26px -12px rgb(0 0 0 / 0.42);
  --sh-press: 0 0 0 rgb(0 0 0 / 0), 0 2px 5px -3px rgb(0 0 0 / 0.36);
  background: var(--mk-bg, #f3f0e8); color: var(--mk-ink, #11110f); font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif); overflow-x: clip;
}
:global([data-theme='dark']) .root {
  --sh-rest: 0 1px 1.5px rgb(0 0 0 / 0.5), 0 6px 16px -8px rgb(0 0 0 / 0.7);
  --sh-lift: 0 1px 1px rgb(0 0 0 / 0.45), 0 16px 28px -12px rgb(0 0 0 / 0.8);
  --sh-press: 0 0 0 rgb(0 0 0 / 0), 0 2px 5px -3px rgb(0 0 0 / 0.7);
}
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }

/* ── Hero ──────────────────────────────────────────────────────────────── */
.hero {
  display: grid; grid-template-columns: minmax(0, 1fr); grid-template-areas: 'head' 'stage' 'rest';
  gap: 22px; max-width: 1440px; margin: 0 auto; padding: 24px 16px 56px;
}
.heroHead { grid-area: head; }
.stageCol { grid-area: stage; min-width: 0; }
.heroRest { grid-area: rest; }
@container (min-width: 1000px) {
  .hero { grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); grid-template-areas: 'head stage' 'rest stage'; grid-template-rows: auto 1fr; column-gap: clamp(40px, 5cqi, 88px); row-gap: 0; padding: 40px 40px 96px; }
  .heroHead { padding-top: 24px; }
}
.maker { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin: 0; font-weight: 600; font-size: 1.0625rem; letter-spacing: 0.01em; }
.tag { padding: 3px 9px; border: 1px solid var(--mk-line-strong, #11110f); border-radius: 999px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; font-weight: 400; letter-spacing: 0.06em; text-transform: uppercase; }
.title { max-width: 12ch; margin: 16px 0 0; font-weight: 300; font-size: clamp(2.625rem, 1.3rem + 4.6cqi, 5.5rem); line-height: 0.98; letter-spacing: -0.05em; text-wrap: balance; }
/* Each word rises inside its own clip box (the headline entrance). */
.mask { display: inline-block; overflow: clip; padding-block: 0.06em 0.16em; margin-block: -0.06em -0.16em; vertical-align: top; }
.word { display: inline-block; }
.lede { max-width: 44ch; margin: 0; font-size: 1.0625rem; line-height: 1.55; color: var(--mk-ink-muted, #5c5a52); text-wrap: pretty; }
@container (min-width: 1000px) { .lede { margin-top: 24px; } }

/* Colourway picker: lit swatches that lift under the pointer and press in. */
.colours { min-inline-size: 0; margin: 28px 0 0; padding: 0; border: 0; }
.colourLegend { margin-bottom: 10px; padding: 0; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.colourLegend span { margin-left: 8px; font-family: var(--mk-font-text, ui-sans-serif, sans-serif); font-size: 0.9375rem; letter-spacing: 0; text-transform: none; color: var(--mk-ink, #11110f); }
.swatches { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; max-width: 460px; }
.swatch {
  position: relative; display: grid; justify-items: center; align-content: start; gap: 8px; padding: 10px 4px 8px; border-radius: 16px; cursor: pointer; text-align: center;
  transition: background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.swatch:hover { background: var(--mk-surface-2, #e9e5da); }
.swatch:has(:focus-visible) { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
.swatchInput { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: pointer; }
.swatchDot {
  --ring: 0 0 0 0 transparent, 0 0 0 0 transparent;
  width: 44px; height: 44px; border-radius: 50%; pointer-events: none;
  background:
    radial-gradient(circle at 32% 26%, rgb(255 255 255 / 0.42), rgb(255 255 255 / 0) 42%),
    radial-gradient(circle at 68% 32%, var(--b) 0 21%, transparent 22%),
    radial-gradient(circle at 60% 75%, rgb(0 0 0 / 0.22), transparent 60%),
    var(--a);
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--mk-ink, #11110f) 22%, transparent), var(--ring), var(--sh-rest);
  transition: transform var(--press-dur, 330ms) var(--press, ease), box-shadow var(--press-dur, 330ms) var(--press, ease);
}
.swatch:hover .swatchDot { transform: translateY(-2px); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--mk-ink, #11110f) 22%, transparent), var(--ring), var(--sh-lift); }
.swatch:active .swatchDot { transform: translateY(1px) scale(0.93); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--mk-ink, #11110f) 22%, transparent), var(--ring), var(--sh-press); transition-duration: var(--mk-duration-instant, 90ms); transition-timing-function: var(--mk-ease-standard, ease); }
.swatch:has(:checked) .swatchDot { --ring: 0 0 0 3px var(--mk-bg, #f3f0e8), 0 0 0 5px var(--mk-ink, #11110f); }
.swatchName { pointer-events: none; font-size: 0.75rem; line-height: 1.25; color: var(--mk-ink-muted, #5c5a52); }
.swatch:has(:checked) .swatchName { color: var(--mk-ink, #11110f); font-weight: 600; }

/* Price + action */
.buy { display: flex; flex-wrap: wrap; align-items: center; gap: 16px 24px; margin-top: 28px; }
.price { display: grid; gap: 4px; margin: 0; }
.priceValue { font-weight: 300; font-size: 2.5rem; line-height: 1; letter-spacing: -0.04em; font-variant-numeric: tabular-nums; }
.priceNote { font-size: 0.8125rem; color: var(--mk-ink-muted, #5c5a52); }
.bagNote { min-height: 1.4em; margin: 12px 0 0; font-size: 0.875rem; color: var(--mk-ink-muted, #5c5a52); }

/* ── Buttons: every press has depth (hover lifts, press compresses, release springs back) ── */
.primary, .secondary, .presetBtn, .iconBtn, .detailBtn {
  transition:
    transform var(--press-dur, 330ms) var(--press, ease), box-shadow var(--press-dur, 330ms) var(--press, ease),
    background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.primary, .secondary {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 52px; padding: 0 26px; border-radius: 999px; cursor: pointer;
  font: 600 1rem/1 var(--mk-font-text, ui-sans-serif, sans-serif); white-space: nowrap;
}
.primary {
  border: 0; background: var(--mk-signal, #bf2f09); color: var(--mk-on-signal, #fff);
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.22), 0 1px 1.5px rgb(0 0 0 / 0.24), 0 8px 18px -8px color-mix(in oklab, var(--mk-signal, #bf2f09) 75%, #000);
}
.primary:hover { background: color-mix(in oklab, var(--mk-signal, #bf2f09) 88%, #000); transform: translateY(-2px); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.22), 0 1px 1px rgb(0 0 0 / 0.16), 0 16px 26px -12px color-mix(in oklab, var(--mk-signal, #bf2f09) 80%, #000); }
.primary:active { transform: translateY(1px) scale(0.98); box-shadow: inset 0 2px 3px rgb(0 0 0 / 0.22), 0 0 0 rgb(0 0 0 / 0), 0 2px 5px -3px color-mix(in oklab, var(--mk-signal, #bf2f09) 70%, #000); transition-duration: var(--mk-duration-instant, 90ms); transition-timing-function: var(--mk-ease-standard, ease); }
.secondary { min-height: 44px; padding: 0 18px; border: 1.5px solid var(--mk-ink, #11110f); background: var(--mk-bg, #f3f0e8); color: var(--mk-ink, #11110f); font-size: 0.9375rem; box-shadow: var(--sh-rest); }
.secondary:hover { background: var(--mk-surface, #fbf9f4); transform: translateY(-2px); box-shadow: var(--sh-lift); }
.secondary:active { transform: translateY(1px) scale(0.98); box-shadow: var(--sh-press); transition-duration: var(--mk-duration-instant, 90ms); transition-timing-function: var(--mk-ease-standard, ease); }
.secondary svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linejoin: round; }
.secondary:disabled { cursor: progress; color: var(--mk-ink-muted, #5c5a52); border-color: var(--mk-ink-muted, #5c5a52); transform: none; box-shadow: none; }
.primary:focus-visible, .secondary:focus-visible, .marker:focus-visible, .presetBtn:focus-visible, .iconBtn:focus-visible, .textBtn:focus-visible, .lens:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 3px; }

/* ── Stage ─────────────────────────────────────────────────────────────── */
.stage {
  --L: clamp(104px, 20cqi, 148px); /* loupe diameter */
  position: relative; margin: 0; aspect-ratio: 1 / 1; overflow: hidden; border-radius: 28px; isolation: isolate;
  background: var(--stage-light, var(--mk-surface-2, #e9e5da)); scroll-margin: 60px 0 16px;
}
:global([data-theme='dark']) .stage, :global([data-theme='dark']) .crop, :global([data-theme='dark']) .closing { background: var(--stage-dark, var(--mk-surface-2, #22221e)); }
@container (min-width: 1000px) { .stage { aspect-ratio: auto; height: min(74dvh, 720px); min-height: 520px; } }

.layers { position: absolute; inset: 0; transition: opacity var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease); }
.layers[data-hidden] { opacity: 0; pointer-events: none; }
.layer { position: absolute; inset: 0; background: var(--tint-l); }
:global([data-theme='dark']) .layer { background: var(--tint-d); }
/* The square box the render (and everything anchored to it) lives in. */
.box { position: absolute; top: 0; bottom: 0; left: 50%; height: 100%; aspect-ratio: 1 / 1; max-width: 100%; translate: -50% 0; }
.box[data-overlay] { z-index: 5; pointer-events: none; }
.tilt { position: absolute; inset: 0; transform: perspective(1500px) rotateX(calc(var(--rx, 0) * 1deg)) rotateY(calc(var(--ry, 0) * 1deg)); }
.poster { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; user-select: none; -webkit-user-drag: none; }

/* Floor: ambient + contact shadow, sliding away from the light (the pointer on hover, top-left at rest). */
.floor { position: absolute; inset: 0; pointer-events: none; }
.ambient, .contact { position: absolute; border-radius: 50%; translate: -50% -50%; }
.ambient {
  left: 51%; top: 81%; width: 70%; height: 10%;
  background: radial-gradient(closest-side, rgb(20 18 14 / 0.3), rgb(20 18 14 / 0.12) 55%, transparent);
  filter: blur(7px);
  transform: translate(calc((50 - var(--hx, 30)) * 0.42px), calc((50 - var(--hy, 22)) * -0.1px)) scale(calc(1 + var(--glow, 0) * 0.05));
}
.contact {
  left: 52%; top: 80%; width: 50%; height: 3.6%;
  background: radial-gradient(closest-side, rgb(14 12 10 / 0.46), transparent);
  filter: blur(2.5px);
  transform: translate(calc((50 - var(--hx, 30)) * 0.12px), 0);
}
:global([data-theme='dark']) .ambient { background: radial-gradient(closest-side, rgb(0 0 0 / 0.62), rgb(0 0 0 / 0.28) 55%, transparent); }
:global([data-theme='dark']) .contact { background: radial-gradient(closest-side, rgb(0 0 0 / 0.8), transparent); }

/* Specular sheen under the light, masked to the product's own silhouette. */
.sheen {
  position: absolute; inset: 0; pointer-events: none;
  mask-size: 100% 100%; mask-repeat: no-repeat; -webkit-mask-size: 100% 100%; -webkit-mask-repeat: no-repeat;
  background:
    radial-gradient(circle at calc(var(--hx, 30) * 1%) calc(var(--hy, 22) * 1%), rgb(255 255 255 / calc(0.16 + var(--glow, 0) * 0.34)), rgb(255 255 255 / 0) 34%),
    linear-gradient(calc(110deg + var(--ry, 0) * 4deg), rgb(255 255 255 / calc(var(--glow, 0) * 0.1)), transparent 45%);
  mix-blend-mode: soft-light;
}

/* Colour wipe: a band in the new accent rides the edge of the incoming layer. */
.band {
  position: absolute; inset: 0; z-index: 4; pointer-events: none; opacity: 0; transform: translateX(-100%);
  background: linear-gradient(90deg, transparent calc(100% - 110px), color-mix(in oklab, var(--band, #ffffff) 45%, transparent) calc(100% - 10px), color-mix(in oklab, var(--band, #ffffff) 55%, #ffffff) 100%);
}

/* Numbered markers: lit discs that lift under the pointer; the open one rides the loupe's rim. */
.marker {
  --m-bg: var(--mk-ink, #11110f); --m-fg: var(--mk-bg, #f3f0e8);
  position: absolute; z-index: 2; display: grid; place-items: center; width: 34px; height: 34px; padding: 0; translate: -50% -50%;
  border: 0; border-radius: 50%; pointer-events: auto; cursor: pointer;
  background: radial-gradient(circle at 34% 28%, color-mix(in oklab, var(--m-bg) 70%, #ffffff), var(--m-bg) 64%);
  color: var(--m-fg); font: 600 0.8125rem/1 var(--mk-font-mono, ui-monospace, monospace);
  box-shadow: 0 0 0 2px var(--mk-bg, #f3f0e8), 0 1px 2px rgb(0 0 0 / 0.35), 0 8px 18px -6px rgb(0 0 0 / 0.45);
  transition:
    translate var(--settle-dur, 490ms) var(--settle, ease), scale var(--press-dur, 330ms) var(--press, ease),
    box-shadow var(--press-dur, 330ms) var(--press, ease), background-color var(--mk-duration-fast, 160ms);
}
.marker:hover { scale: 1.1; box-shadow: 0 0 0 2px var(--mk-bg, #f3f0e8), 0 1px 1px rgb(0 0 0 / 0.25), 0 14px 24px -8px rgb(0 0 0 / 0.5); }
.marker:active { scale: 0.9; box-shadow: 0 0 0 2px var(--mk-bg, #f3f0e8), 0 0 0 rgb(0 0 0 / 0), 0 2px 4px -2px rgb(0 0 0 / 0.4); transition-duration: var(--mk-duration-instant, 90ms); }
.marker[aria-expanded='true'] { --m-bg: var(--mk-signal, #bf2f09); --m-fg: var(--mk-on-signal, #fff); }
.marker[data-rim] { translate: calc(-50% + var(--L) * 0.36) calc(-50% - var(--L) * 0.36); }

/* ── Loupe ─────────────────────────────────────────────────────────────── */
.loupeLayer { position: absolute; top: 0; bottom: 0; left: 50%; z-index: 4; height: 100%; aspect-ratio: 1 / 1; max-width: 100%; translate: -50% 0; pointer-events: none; }
.lens {
  --open: 0;
  position: absolute; left: 0; top: 0; width: var(--L); height: var(--L); padding: 0; border: 0; border-radius: 50%; overflow: hidden;
  transform: translate(-50%, -50%) scale(0.4);
  background: var(--mk-bg, #f3f0e8); color: var(--mk-ink, #11110f);
  pointer-events: auto; touch-action: none; cursor: grab; -webkit-tap-highlight-color: transparent;
  box-shadow:
    0 0 0 3px color-mix(in oklab, var(--mk-ink, #11110f) 86%, transparent),
    0 0 0 4.5px color-mix(in oklab, var(--mk-bg, #f3f0e8) 70%, transparent),
    0 2px 3px rgb(0 0 0 / 0.3),
    0 22px 38px -14px rgb(0 0 0 / 0.5);
  transition: box-shadow var(--press-dur, 330ms) var(--press, ease);
}
.lens[data-moving] { will-change: transform; }
.lens:hover { box-shadow: 0 0 0 3px color-mix(in oklab, var(--mk-ink, #11110f) 86%, transparent), 0 0 0 4.5px color-mix(in oklab, var(--mk-bg, #f3f0e8) 70%, transparent), 0 1px 2px rgb(0 0 0 / 0.22), 0 30px 46px -16px rgb(0 0 0 / 0.55); }
.lens:active { cursor: grabbing; }
.glass {
  position: absolute; inset: 0; border-radius: inherit; background-repeat: no-repeat; background-color: var(--stage-light, #e3e5e8); opacity: var(--open);
}
:global([data-theme='dark']) .glass { background-color: var(--stage-dark, #1d2024); }
.glint {
  position: absolute; inset: 0; border-radius: inherit; pointer-events: none;
  background: radial-gradient(110% 80% at 30% 16%, rgb(255 255 255 / 0.42), rgb(255 255 255 / 0) 44%);
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / 0.35), inset 0 -10px 22px rgb(0 0 0 / calc(var(--open) * 0.22)), inset 0 0 26px rgb(0 0 0 / calc(var(--open) * 0.16));
}
.lensIcon { position: absolute; inset: 0; margin: auto; width: 46%; height: 46%; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; opacity: calc(1 - var(--open)); }

/* Detail card: springs up from the stage floor. */
.detailCard { position: absolute; z-index: 6; left: 14px; right: 14px; bottom: 14px; max-width: 380px; }
.detailCard:not([data-open]) { display: none; }
.detailInner {
  padding: 14px 16px; border-radius: 16px; background: var(--mk-surface, #fbf9f4);
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.14), 0 18px 34px -16px rgb(0 0 0 / 0.38);
  animation: pp-card var(--settle-dur, 490ms) var(--settle, ease) both;
}
@keyframes pp-card { from { opacity: 0; translate: 0 14px; } }
.detailTitle { display: flex; align-items: center; gap: 10px; margin: 0; font-weight: 600; }
.detailTitle span { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: var(--mk-signal, #bf2f09); color: var(--mk-on-signal, #fff); font: 600 0.75rem/1 var(--mk-font-mono, ui-monospace, monospace); }
.detailBody { margin: 6px 0 0; font-size: 0.875rem; line-height: 1.45; color: var(--mk-ink-muted, #5c5a52); }

/* 3D viewer. `will-change: filter` composites the viewer in its own render surface: without it, headless Chromium's
   compositor occlusion-culls the WebGL layer under the gallery's sticky header with the visible rect flipped
   vertically, so a canvas scrolled partly under the header drew only a strip of the model. */
.viewer { position: absolute; inset: 0; z-index: 2; opacity: 0; will-change: filter; transition: opacity var(--mk-duration-moderate, 360ms) var(--mk-ease-standard, ease); }
.viewer[data-ready] { opacity: 1; }
.viewerError { position: absolute; inset: 0; z-index: 4; display: grid; background: var(--mk-surface-2, #e9e5da); }

.stageBar { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; margin-top: 14px; }
.stageNote { flex: 1 1 16rem; margin: 0; font-size: 0.8125rem; line-height: 1.45; color: var(--mk-ink-muted, #5c5a52); }
.viewerStatus { flex: 1 1 100%; margin: 0; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; color: var(--mk-ink-muted, #5c5a52); }
.viewerStatus:empty { display: none; }
.toolbar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px; width: 100%; }
.presets { display: flex; flex-wrap: wrap; gap: 4px; padding: 4px; border-radius: 999px; background: var(--mk-surface-2, #e9e5da); box-shadow: inset 0 1px 2px rgb(0 0 0 / 0.12); }
.presetBtn { min-height: 36px; padding: 0 14px; border: 0; border-radius: 999px; background: transparent; color: var(--mk-ink, #11110f); font: 500 0.8125rem/1 var(--mk-font-text, ui-sans-serif, sans-serif); cursor: pointer; }
.presetBtn:hover:not(:disabled):not([aria-pressed='true']) { background: color-mix(in oklab, var(--mk-surface, #fbf9f4) 70%, transparent); }
.presetBtn:active:not(:disabled) { transform: scale(0.95); transition-duration: var(--mk-duration-instant, 90ms); }
.presetBtn[aria-pressed='true'] { background: var(--mk-ink, #11110f); color: var(--mk-bg, #f3f0e8); box-shadow: var(--sh-rest); }
.presetBtn:disabled, .iconBtn:disabled, .textBtn:disabled { cursor: progress; color: var(--mk-ink-muted, #5c5a52); }
.tools { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.iconBtn { display: grid; place-items: center; width: 44px; height: 44px; border: 1px solid var(--mk-line-strong, #11110f); border-radius: 50%; background: var(--mk-bg, #f3f0e8); color: var(--mk-ink, #11110f); font: 400 1.25rem/1 var(--mk-font-text, ui-sans-serif, sans-serif); cursor: pointer; box-shadow: var(--sh-rest); }
.iconBtn:hover:not(:disabled) { transform: translateY(-2px); box-shadow: var(--sh-lift); }
.iconBtn:active:not(:disabled) { transform: translateY(1px) scale(0.94); box-shadow: var(--sh-press); transition-duration: var(--mk-duration-instant, 90ms); }
.detailRow { display: flex; flex-wrap: wrap; gap: 6px; width: 100%; }
.detailBtn { display: inline-flex; align-items: center; gap: 8px; min-height: 36px; padding: 0 12px 0 6px; border: 1px solid var(--mk-line, #11110f24); border-radius: 999px; background: var(--mk-bg, #f3f0e8); color: var(--mk-ink, #11110f); font: 500 0.8125rem/1.2 var(--mk-font-text, ui-sans-serif, sans-serif); cursor: pointer; text-align: left; }
.detailBtn:hover:not(:disabled) { transform: translateY(-1px); box-shadow: var(--sh-rest); }
.detailBtn:active:not(:disabled) { transform: scale(0.97); box-shadow: none; transition-duration: var(--mk-duration-instant, 90ms); }
.detailBtn span { display: grid; place-items: center; flex: none; width: 24px; height: 24px; border-radius: 50%; background: var(--mk-ink, #11110f); color: var(--mk-bg, #f3f0e8); font: 600 0.75rem/1 var(--mk-font-mono, ui-monospace, monospace); }
.detailBtn[aria-pressed='true'] { border-color: var(--mk-ink, #11110f); }
.detailBtn[aria-pressed='true'] span { background: var(--mk-signal, #bf2f09); color: var(--mk-on-signal, #fff); }
.detailBtn:disabled { cursor: progress; color: var(--mk-ink-muted, #5c5a52); }
.detailBtn:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 3px; }
.textBtn { min-height: 44px; padding: 0 8px; border: 0; background: none; color: var(--mk-ink, #11110f); cursor: pointer; font: 500 0.875rem/1 var(--mk-font-text, ui-sans-serif, sans-serif); text-decoration: underline; text-underline-offset: 3px; transition: text-decoration-thickness var(--mk-duration-fast, 160ms); }
.textBtn:hover:not(:disabled) { text-decoration-thickness: 2px; }
.textBtn:active:not(:disabled) { transform: translateY(1px); }

/* ── Chapters: each opens on the whole product and dollies in on its detail, then zooms ≤ 10 % with the scroll ── */
.chapters { display: grid; gap: clamp(64px, 10cqi, 136px); max-width: 1280px; margin: 0 auto; padding: clamp(32px, 6cqi, 72px) 16px clamp(56px, 8cqi, 112px); }
.chapter { display: grid; gap: 28px; align-items: center; }
@container (min-width: 820px) {
  .chapter { grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); gap: clamp(40px, 6cqi, 104px); }
  .chapter[data-side='right'] { grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); }
  .chapter[data-side='right'] .crop { order: 2; }
  .chapters { padding-inline: 40px; }
}
.crop {
  position: relative; justify-self: center; width: 100%; max-width: 540px; aspect-ratio: 1 / 1; overflow: hidden; border-radius: 28px;
  background: var(--stage-light, var(--mk-surface-2, #e9e5da));
  box-shadow: inset 0 0 0 1px rgb(0 0 0 / 0.04), inset 0 -40px 60px -40px rgb(0 0 0 / 0.12);
  transition: background-color var(--mk-duration-moderate, 360ms) var(--mk-ease-standard, ease);
}
.crop[data-shape='circle'] { border-radius: 50%; }
.crop[data-shape='pill'] { max-width: 400px; aspect-ratio: 3 / 4; border-radius: 999px; }
.zoomer { position: absolute; inset: 0; transform: scale(calc(1 + var(--sp, 0) * 0.1)); }
.crop img {
  position: absolute; top: 50%; left: 50%; width: auto; height: 100%; aspect-ratio: 1 / 1; translate: -50% -50%;
  transform-origin: var(--fx) var(--fy);
  transform: translate(calc(50% - var(--fx)), calc(50% - var(--fy))) scale(var(--zoom));
}
.chapter[data-reveal='wait'] .crop img { transform: none; }
.chapter[data-reveal='wait'] .chapterText { opacity: 0; transform: translateY(24px); }
@media (prefers-reduced-motion: no-preference) {
  .root:not([data-reduced]) .crop img { transition: transform 1100ms var(--mk-ease-emphasized, ease); }
  .root:not([data-reduced]) .chapterText { transition: opacity var(--mk-duration-slow, 560ms) var(--mk-ease-standard, ease) 120ms, transform var(--mk-duration-slow, 560ms) var(--mk-ease-emphasized, ease) 120ms; }
}
.chapterNum { margin: 0 0 18px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; letter-spacing: 0.1em; color: var(--mk-signal, #bf2f09); }
.chapterTitle { max-width: 14ch; margin: 0; font-weight: 300; font-size: clamp(2rem, 1.1rem + 3cqi, 3.5rem); line-height: 1.02; letter-spacing: -0.045em; text-wrap: balance; }
.chapterBody { max-width: 46ch; margin: 18px 0 0; font-size: 1.0625rem; line-height: 1.6; color: var(--mk-ink-muted, #5c5a52); text-wrap: pretty; }

/* ── Specification ─────────────────────────────────────────────────────── */
.specs { display: grid; gap: 28px; max-width: 1280px; margin: 0 auto; padding: clamp(56px, 8cqi, 104px) 16px; border-top: 1px solid var(--mk-line, #11110f24); }
@container (min-width: 900px) { .specs { grid-template-columns: minmax(0, 4fr) minmax(0, 8fr); padding-inline: 40px; } }
.sectionTitle { margin: 0; font-weight: 300; font-size: clamp(1.875rem, 1rem + 2.6cqi, 2.875rem); line-height: 1.05; letter-spacing: -0.04em; }
.specsNote { max-width: 34ch; margin: 14px 0 0; font-size: 0.875rem; line-height: 1.5; color: var(--mk-ink-muted, #5c5a52); }
.table { width: 100%; border-collapse: collapse; font-size: 0.9375rem; }
.table th { width: 8.5rem; padding: 15px 16px 13px 0; border-top: 1px solid var(--mk-line, #11110f24); vertical-align: top; text-align: left; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; font-weight: 400; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.table td { padding: 12px 0; border-top: 1px solid var(--mk-line, #11110f24); line-height: 1.5; }
.table tr:last-child th, .table tr:last-child td { border-bottom: 1px solid var(--mk-line, #11110f24); }
.source { font-size: 0.8125rem; color: var(--mk-ink-muted, #5c5a52); }

/* ── Why 3D waits ──────────────────────────────────────────────────────── */
.why3d { display: grid; gap: 18px; max-width: 1280px; margin: 0 auto; padding: 0 16px clamp(56px, 8cqi, 104px); }
.why3d p { max-width: 64ch; margin: 0; font-size: 1.0625rem; line-height: 1.6; color: var(--mk-ink-muted, #5c5a52); }
.why3d em { font-style: normal; color: var(--mk-ink, #11110f); font-weight: 600; }
@container (min-width: 900px) { .why3d { grid-template-columns: minmax(0, 4fr) minmax(0, 8fr); padding-inline: 40px; } }

/* ── Closing ───────────────────────────────────────────────────────────── */
.closing {
  display: grid; justify-items: start; gap: 22px; max-width: 1360px; margin: 0 16px 40px; padding: clamp(40px, 7cqi, 96px) clamp(22px, 6cqi, 80px);
  border-radius: 28px; background: var(--stage-light, var(--mk-surface-2, #e9e5da));
  transition: background-color var(--mk-duration-moderate, 360ms) var(--mk-ease-standard, ease);
}
@container (min-width: 1400px) { .closing { margin-inline: auto; } }
.closingTitle { max-width: 16ch; margin: 0; font-weight: 300; font-size: clamp(2.125rem, 1.2rem + 3.6cqi, 4.25rem); line-height: 1; letter-spacing: -0.05em; text-wrap: balance; }
.closingNote { max-width: 60ch; margin: 0; font-size: 0.8125rem; line-height: 1.5; color: var(--mk-ink-muted, #5c5a52); }

/* ── Reduced motion: no light, travel or spring; state changes are instant or a short fade ── */
.root[data-reduced] .primary, .root[data-reduced] .secondary, .root[data-reduced] .presetBtn, .root[data-reduced] .iconBtn,
.root[data-reduced] .detailBtn, .root[data-reduced] .marker, .root[data-reduced] .swatchDot, .root[data-reduced] .lens { transition: none; }
.root[data-reduced] .primary:hover, .root[data-reduced] .secondary:hover, .root[data-reduced] .iconBtn:hover, .root[data-reduced] .detailBtn:hover,
.root[data-reduced] .swatch:hover .swatchDot { transform: none; }
.root[data-reduced] .marker:hover { scale: 1; }
.root[data-reduced] .detailInner { animation: pp-fade 160ms linear both; }
@keyframes pp-fade { from { opacity: 0; } }
@media (prefers-reduced-motion: reduce) {
  .primary, .secondary, .presetBtn, .iconBtn, .detailBtn, .marker, .swatchDot, .lens { transition: none; }
}

'use client';
/**
 * The optional 3D view, loaded as its own chunk only after "Explore in 3D" is pressed.
 * The page owns every piece of state (colourway, camera preset, open annotation); this is a pure view of it.
 */
import { Suspense, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState, type Ref } from 'react';
import {
  CameraRig, HotspotAnchors, HotspotLayer, LightingRig, Model, ModelBoundary, OrbitInspect, PartController, SceneFallback, StudioCanvas,
  defaultQualityProfiles, describeModelError, formatBytes, resolveModelUrl, resolveModelVariant, useHotspotStore, useModelManifest, useModelProgress,
  type CameraRigHandle, type LoadedModel, type OrbitInspectHandle, type QualityLevel,
} from '../../../three';
import { DETAILS, MANIFEST_URL, POSTER, PRESETS, SCALE, type Colourway, type PresetId } from './data';
import styles from './styles.module.css';

export interface ViewerHandle { zoom(factor: number): void; reset(): void }
export interface ViewerStatus { phase: 'loading' | 'ready' | 'error'; text: string }

interface Props {
  colourway: Colourway;
  preset: PresetId | null;
  active: string | null;
  onSelect: (id: string | null) => void;
  onLeavePreset: () => void;
  onStatus: (s: ViewerStatus) => void;
  handle?: Ref<ViewerHandle>;
}

export default function Viewer3D({ colourway, preset, active, onSelect, onLeavePreset, onStatus, handle }: Props) {
  const orbit = useRef<OrbitInspectHandle>(null);
  const rig = useRef<CameraRigHandle>(null);
  const store = useHotspotStore();
  const [level, setLevel] = useState<QualityLevel | null>(null);
  const [loaded, setLoaded] = useState<LoadedModel | null>(null);
  const [error, setError] = useState<Error | null>(null);
  const [attempt, setAttempt] = useState(0);

  const { manifest, error: manifestError } = useModelManifest(MANIFEST_URL);
  const variant = manifest && level ? resolveModelVariant(manifest, defaultQualityProfiles[level].modelVariant) : null;
  const url = variant ? resolveModelUrl(variant.file, MANIFEST_URL) : null;
  const progress = useModelProgress(url);
  const failure = error ?? manifestError;

  useImperativeHandle(handle, () => ({
    zoom: (f) => { orbit.current?.zoom(f); onLeavePreset(); },
    reset: () => { orbit.current?.reset(); rig.current?.goTo('hero'); },
  }), [onLeavePreset]);

  useEffect(() => {
    if (failure) onStatus({ phase: 'error', text: describeModelError(failure) });
    else if (loaded) onStatus({ phase: 'ready', text: `3D view ready${variant ? ` (${variant.profile} build, ${formatBytes(variant.bytes)})` : ''}. Drag or use the arrow keys on the view to turn it.` });
    else onStatus({ phase: 'loading', text: variant ? `Loading the ${variant.profile} build: ${progress.fraction != null ? `${Math.round(progress.fraction * 100)}%` : formatBytes(progress.loaded)} of ${formatBytes(variant.bytes)}` : 'Preparing the 3D view…' });
  }, [failure, loaded, variant, progress.fraction, progress.loaded, onStatus]);

  const onLoaded = useCallback((m: LoadedModel) => { setLoaded(m); setError(null); }, []);
  useEffect(() => { setLoaded(null); }, [url, attempt]);
  const hotspots = useMemo(() => DETAILS.map(({ id, node, position, label, description }) => ({ id, node, position, label, description })), []);

  if (failure) {
    return (
      <div className={styles.viewerError}>
        <SceneFallback title="Pulse speaker" image={POSTER} imageAlt="Studio render of the Pulse speaker in Graphite & Ember" reason={describeModelError(failure)}>
          <button type="button" className={styles.secondary} onClick={() => { setError(null); setAttempt((a) => a + 1); }}>Try the 3D view again</button>
        </SceneFallback>
      </div>
    );
  }

  return (
    <div className={styles.viewer} data-ready={loaded ? 'true' : undefined}>
      <StudioCanvas
        label={`Pulse speaker in ${colourway.name}, interactive 3D view`}
        description="Drag to turn the speaker, or focus the view and use the arrow keys to rotate and plus or minus to zoom. Numbered markers name the driver, the dial and the strap."
        lazy={false}
        onQualityChange={setLevel}
        onSceneError={setError}
        camera={{ fov: 30, near: 0.1, far: 80, position: PRESETS.hero.position }}
        style={{ position: 'absolute', inset: 0 }}
        fallback={<SceneFallback title="Pulse speaker" image={POSTER} imageAlt="Studio render of the Pulse speaker in Graphite & Ember" description="The photo and every detail on this page stay available without 3D." />}
      >
        <LightingRig preset="studio-soft" shadowRadius={1.5} />
        <OrbitInspect ref={orbit} target={[0, 0.75, 0]} minDistance={2.4} maxDistance={10} maxPolarAngle={Math.PI * 0.58} onStart={onLeavePreset} />
        <CameraRig ref={rig} presets={PRESETS} preset={preset ?? undefined} smoothTime={0.55} onInterrupt={onLeavePreset} />
        {url ? (
          <ModelBoundary resetKey={`${url}#${attempt}`} onError={setError}>
            <Suspense fallback={null}>
              <Model key={attempt} src={url} scale={SCALE} castShadow onLoaded={onLoaded} onError={setError} />
              <PartController root={loaded?.scene ?? null} overrides={colourway.overrides} />
              <HotspotAnchors store={store} hotspots={hotspots} root={loaded?.scene ?? null} />
            </Suspense>
          </ModelBoundary>
        ) : null}
      </StudioCanvas>
      {loaded ? <HotspotLayer store={store} hotspots={hotspots} active={active} onSelect={onSelect} /> : null}
    </div>
  );
}
